$chars = [char[]]'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
function R($n){ -join (1..$n | % { $chars | Get-Random }) }
$args = @('create','secret','generic','wordpress-secrets','-n','bench-claude',
 "--from-literal=mysql-root-password=<redacted> 24)","--from-literal=mysql-password=<redacted> 24)")
foreach($k in 'AUTH_KEY','SECURE_AUTH_KEY','LOGGED_IN_KEY','NONCE_KEY','AUTH_SALT','SECURE_AUTH_SALT','LOGGED_IN_SALT','NONCE_SALT'){ $args += "--from-literal=WORDPRESS_$k=$(R 64)" }
kubectl @args
